  (* [comment removed for export] *)
  Lemma pcm_B : forall regs m (s cm : Z),
    (48 <= s)%Z -> (s < 2 ^ 64)%Z ->
    rdn SEGS m (Z_to_bv 64 (s - 36)) 4 = Some (Z_to_le_bytes 4 1) ->
    getr regs 2 = Z_to_bv 64 (s - 48) -> getr regs 8 = Z_to_bv 64 cm ->
    exists regs',
      msteps SEGS (mkst regs (0x19858 : word) m rom) (mkst regs' (0x1c5d8 : word) m rom)
      /\ getr regs' 2 = Z_to_bv 64 (s - 48) /\ getr regs' 1 = Z_to_bv 64 0x19868 /\ getr regs' 10 = Z_to_bv 64 cm
      /\ regs_agree (fun r => In r [1; 10]%list) regs regs'.
